# Generated by build.py from recipe.yml for recipe http-limit-connections. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'per', 'free' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/slow.txt'), "slow`n")
[IO.File]::WriteAllText((Join-Path $PWD 'per/slow.txt'), "slow`n")
[IO.File]::WriteAllText((Join-Path $PWD 'free/slow.txt'), "slow`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--max-connections', '1', '--fault', '"delay;stage=command;path=/slow.txt;ms=2000"', 'http://127.0.0.1:8080/', 'http://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -Z --parallel-immediate -o NUL -o NUL -w "%{http_code}\n" http://127.0.0.1:8080/slow.txt http://127.0.0.1:8080/slow.txt } finally { Stop-Process $server0 }
